import subprocess, os, textwrap
exe = os.path.abspath("executable")
def run(args, cwd='/tmp/dtest', inp=''):
    p = subprocess.run(args, capture_output=True, text=True, input=inp, timeout=10, cwd=cwd)
    return p

# Base empty func is 6 tokens (max t=6). Good, matches earlier base 6.
# Now measure if, for, etc. by adding single statement to base and seeing max t increase.

def max_t_for(code):
    import os as _os
    _os.system("rm -rf /tmp/dtest; mkdir -p /tmp/dtest")
    open('/tmp/dtest/a.go','w').write(code)
    open('/tmp/dtest/b.go','w').write(code)
    for t in range(1,100):
        p = run([exe, '-t', str(t)])
        has_whole = "a.go:1," in p.stdout
        if not has_whole:
            return t-1
    return 100

tests = [
    ("empty", "package main
func foo() {
}
"),
    ("assign", "package main
func foo() {
    x := 1
}
"),
    ("println builtin", "package main
func foo() {
    println(1)
}
"),
    ("fmt println", 'package main
import "fmt"
func foo() {
    fmt.Println(1)
}
'),
    ("if empty", "package main
func foo() {
    if true {
    }
}
"),
    ("if with 1 println", "package main
func foo() {
    if true {
        println(1)
    }
}
"),
    ("if with 3 println", "package main
func foo() {
    if true {
        println(1)
        println(2)
        println(3)
    }
}
"),
    ("for empty", "package main
func foo() {
    for i := 0; i < 10; i++ {
    }
}
"),
    ("for with 1 println", "package main
func foo() {
    for i := 0; i < 10; i++ {
        println(i)
    }
}
"),
    ("return", "package main
func foo() int {
    return 1
}
"),
    ("return x", "package main
func foo() int {
    x := 1
    return x
}
"),
    ("binary expr", "package main
func foo() {
    x := 1 + 2
}
"),
    ("binary 4 ops", "package main
func foo() {
    x := 1 + 2 + 3 + 4 + 5
}
"),
]

for name, code in tests:
    mt = max_t_for(code)
    print(f"{name}: max_t={mt} delta={mt-6}")

