type parsedFile struct {
	name       string
	src        []byte
	seq        []int
	starts     []int // byte offsets
	ends       []int
	lineStarts []int // offsets of line starts
}

func computeLineStarts(src []byte) []int {
	ls := []int{0}
	for i, b := range src {
		if b == '\n' {
			ls = append(ls, i+1)
		}
	}
	return ls
}

func offsetToLine(lineStarts []int, off int) int {
	// binary search: largest i with lineStarts[i] <= off, line = i+1
	lo, hi := 0, len(lineStarts)-1
	for lo < hi {
		mid := (lo + hi + 1) / 2
		if lineStarts[mid] <= off {
			lo = mid
		} else {
			hi = mid - 1
		}
	}
	return lo + 1
}

func serializeFile(name string, src []byte) (*parsedFile, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, name, src, 0)
	if err != nil {
		return nil, err
	}
	var seq []int
	var startsPos []token.Pos
	var endsPos []token.Pos
	ast.Inspect(f, func(n ast.Node) bool {
		if n == nil {
			return true
		}
		if gd, ok := n.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			return false
		}
		seq = append(seq, tokenForNode(n))
		startsPos = append(startsPos, n.Pos())
		endsPos = append(endsPos, n.End())
		return true
	})
	// remove File.Name (index 1)
	if len(seq) >= 2 {
		seq = append(seq[:1], seq[2:]...)
		startsPos = append(startsPos[:1], startsPos[2:]...)
		endsPos = append(endsPos[:1], endsPos[2:]...)
	}
	// convert Pos to offsets
	file := fset.File(f.Pos())
	starts := make([]int, len(seq))
	ends := make([]int, len(seq))
	for i := range seq {
		starts[i] = file.Offset(startsPos[i])
		ends[i] = file.Offset(endsPos[i])
	}
	ls := computeLineStarts(src)
	return &parsedFile{name: name, src: src, seq: seq, starts: starts, ends: ends, lineStarts: ls}, nil
}

type clone struct {
	fileIdx int
	startTok int
	endTok int // exclusive? Actually inclusive? Let's use start index in seq, length
	length int
	startOff int
	endOff int
	startLine int
	endLine int
}

type cloneGroup struct {
	clones []clone
	// for sorting groups: token sequence of first clone (length tokens, values)
	tokens []int
}

func runWithFiles(validFiles []fileData, threshold int, htmlFlag, plumbingFlag, verboseFlag bool) {
	// parse and serialize
	var pfiles []*parsedFile
	for _, fd := range validFiles {
		pf, err := serializeFile(fd.name, fd.src)
		if err != nil {
			log.Println(err)
			continue
		}
		pfiles = append(pfiles, pf)
	}
	if verboseFlag {
		log.Println("Searching for clones")
	}
	if threshold < 1 {
		threshold = 1
	}
	groups := findClones(pfiles, threshold)
	// output
	if htmlFlag {
		fmt.Print("<!DOCTYPE html>\n<meta charset=\"utf-8\"/>\n<title>Duplicates</title>\n<style>\n\tpre {\n\t\tbackground-color: #FFD;\n\t\tborder: 1px solid #E2E2E2;\n\t\tpadding: 1ex;\n\t}\n</style>\n")
		for i, g := range groups {
			fmt.Printf("<h1>#%d found %d clones</h1>\n", i+1, len(g.clones))
			for _, c := range g.clones {
				pf := pfiles[c.fileIdx]
				frag := extractFragment(pf, c)
				esc := html.EscapeString(frag)
				fmt.Printf("<h2>%s:%d</h2>\n<pre>%s</pre>\n", pf.name, c.startLine, esc)
			}
		}
		return
	}
	if plumbingFlag {
		for _, g := range groups {
			n := len(g.clones)
			for i, c := range g.clones {
				nxt := g.clones[(i+1)%n]
				pf := pfiles[c.fileIdx]
				pf2 := pfiles[nxt.fileIdx]
				fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n", pf.name, c.startLine, c.endLine, pf2.name, nxt.startLine, nxt.endLine)
			}
		}
		return
	}
	for _, g := range groups {
		fmt.Printf("found %d clones:\n", len(g.clones))
		for _, c := range g.clones {
			pf := pfiles[c.fileIdx]
			fmt.Printf("  %s:%d,%d\n", pf.name, c.startLine, c.endLine)
		}
	}
	if len(groups) == 0 {
		fmt.Printf("\nFound total 0 clone groups.\n")
	} else {
		fmt.Printf("\nFound total %d clone groups.\n", len(groups))
	}
}

