cat > main.go <<'GO'
package main

import (
	"bufio"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"html"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

var usageText = `Usage: dupl [flags] [paths]

Paths:
  If the given path is a file, dupl will use it regardless of
  the file extension. If it is a directory, it will recursively
  search for *.go files in that directory.

  If no path is given, dupl will recursively search for *.go
  files in the current directory.

Flags:
  -files
    	read file names from stdin one at each line
  -html
    	output the results as HTML, including duplicate code fragments
  -plumbing
    	plumbing (easy-to-parse) output for consumption by scripts or tools
  -t, -threshold size
    	minimum token sequence size as a clone (default 15)
  -vendor
    	check files in vendor directory
  -v, -verbose
    	explain what is being done

Examples:
  dupl -t 100
    	Search clones in the current directory of size at least
    	100 tokens.
  dupl $(find app/ -name '*_test.go')
    	Search for clones in tests in the app directory.
  find app/ -name '*_test.go' |dupl -files
    	The same as above.
`

type fileData struct {
	name string
	src  []byte
}

func main() {
	var (
		filesFlag    bool
		htmlFlag     bool
		plumbingFlag bool
		threshold    int
		vendorFlag   bool
		verboseFlag  bool
	)
	fs := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	fs.BoolVar(&filesFlag, "files", false, "")
	fs.BoolVar(&htmlFlag, "html", false, "")
	fs.BoolVar(&plumbingFlag, "plumbing", false, "")
	fs.IntVar(&threshold, "t", 15, "")
	fs.IntVar(&threshold, "threshold", 15, "")
	fs.BoolVar(&vendorFlag, "vendor", false, "")
	fs.BoolVar(&verboseFlag, "v", false, "")
	fs.BoolVar(&verboseFlag, "verbose", false, "")
	fs.Usage = func() {
		fmt.Fprint(fs.Output(), usageText)
	}
	if err := fs.Parse(os.Args[1:]); err != nil {
		os.Exit(2)
	}
	if htmlFlag && plumbingFlag {
		log.Fatal("you can have either plumbing or HTML output")
	}
	if filesFlag {
		reader := bufio.NewScanner(os.Stdin)
		const maxCap = 10 * 1024 * 1024
		buf := make([]byte, 0, 64*1024)
		reader.Buffer(buf, maxCap)
		var stdinNames []string
		for reader.Scan() {
			line := reader.Text()
			if strings.HasPrefix(line, "./") {
				line = line[2:]
			}
			stdinNames = append(stdinNames, line)
		}
		if verboseFlag {
			log.Println("Building suffix tree")
		}
		seenFiles := make(map[string]bool)
		var uniq []string
		for _, n := range stdinNames {
			if !seenFiles[n] {
				seenFiles[n] = true
				uniq = append(uniq, n)
			}
		}
		var validFiles []fileData
		for _, name := range uniq {
			src, err := os.ReadFile(name)
			if err != nil {
				log.Println(err)
				continue
			}
			validFiles = append(validFiles, fileData{name, src})
		}
		runWithFiles(validFiles, threshold, htmlFlag, plumbingFlag, verboseFlag)
		return
	}
	args := fs.Args()
	if len(args) == 0 {
		args = []string{"."}
	}
	var collected []string
	collectedSeen := make(map[string]bool)
	collectAdd := func(name string) {
		if !collectedSeen[name] {
			collectedSeen[name] = true
			collected = append(collected, name)
		}
	}
	for _, p := range args {
		fi, err := os.Lstat(p)
		if err != nil {
			log.Fatal(err)
		}
		if fi.IsDir() {
			err := filepath.Walk(p, func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return nil
				}
				if info.IsDir() {
					if !vendorFlag && info.Name() == "vendor" {
						return filepath.SkipDir
					}
					return nil
				}
				if !strings.HasSuffix(path, ".go") {
					return nil
				}
				collectAdd(path)
				return nil
			})
			if err != nil {
				log.Fatal(err)
			}
		} else {
			collectAdd(p)
		}
	}
	if verboseFlag {
		log.Println("Building suffix tree")
	}
	var validFiles []fileData
	for _, name := range collected {
		src, err := os.ReadFile(name)
		if err != nil {
			log.Println(err)
			continue
		}
		validFiles = append(validFiles, fileData{name, src})
	}
	runWithFiles(validFiles, threshold, htmlFlag, plumbingFlag, verboseFlag)
}

